-- DarkChaos: class spell ranks for levels 81-255 (generated by tools/balance/gen_class_ranks.py)
-- Classes: mage, warrior, paladin, hunter, rogue, priest, deathknight, shaman, warlock, druid, warlock_pet, hunter_pet.
--
-- 248 spell families get one new rank per band, learned at 81, 100, 130, 160. Spell ids 921000-932999; their Spell.dbc
-- and SkillLineAbility.dbc rows ship with this file (the server needs both DBC files before it).
-- Damage grows like weapon damage and heals/absorbs like player health (tools/balance/gen_reference.py);
-- flat buffs grow with gear (spell power, attack power, mana per 5), stats, health or the armor formula;
-- coefficients, costs and spell class masks are the level-80 rank's. The level-80 ranks are not changed.
-- Totems get a copy of their creature per band, traps a copy of their object, weapon imbues a copy
-- of their enchantment (SpellItemEnchantment.dbc rows ship with this file too). Pet abilities
-- (warlock_pet, hunter_pet) are learned by the pets at the band level, without a trainer.
--
-- For every new rank this file adds: the rank chain (spell_ranks); the trainer offer (every trainer that
-- teaches the level-80 rank, at the band level, previous rank required, same price); the spell power
-- coefficient (spell_bonus_data, copied from the row the core uses for the level-80 rank); and copies
-- of the rows the level-80 rank has under its own id: spell_script_names, spell_custom_attr,
-- spell_threat (flat threat grown like a white hit) and spell_linked_spell (a linked child moves to the
-- same band's copy).
-- Re-running gives the same result. Apply to acore_world, then restart the worldserver.

DROP TEMPORARY TABLE IF EXISTS `dc_tmp_rank_map`;
CREATE TEMPORARY TABLE `dc_tmp_rank_map` (`new_id` INT NOT NULL PRIMARY KEY, `top_id` INT NOT NULL, `step` TINYINT UNSIGNED NOT NULL, `band` TINYINT UNSIGNED NOT NULL, `prev_id` INT NOT NULL, `is_parent` TINYINT UNSIGNED NOT NULL, `growth` FLOAT NOT NULL, `bonus_src` INT NOT NULL DEFAULT 0) ENGINE=InnoDB;
DELETE FROM `dc_tmp_rank_map`;
-- A second copy: a temporary table can be named only once per statement.
DROP TEMPORARY TABLE IF EXISTS `dc_tmp_rank_map2`;
CREATE TEMPORARY TABLE `dc_tmp_rank_map2` ENGINE=InnoDB SELECT `new_id`, `top_id`, `step` FROM `dc_tmp_rank_map`;

-- Stock chain fix: a script walks the ranks of 66216, but stock roots that chain at 59133.
-- Re-rooted at 66216 (the rank chain below adds the new ranks to it again).
DELETE FROM `spell_ranks` WHERE `first_spell_id` IN (59133, 66216);

-- Rank chain
DELETE FROM `spell_ranks` WHERE `spell_id` BETWEEN 921000 AND 932999;

-- Trainer offers
DELETE FROM `trainer_spell` WHERE `SpellId` BETWEEN 921000 AND 932999;

-- Spell power coefficients: the core looks a spell up by its own id, then by its first rank's.
UPDATE `dc_tmp_rank_map` SET `bonus_src` = `top_id` WHERE `top_id` IN (SELECT `entry` FROM `spell_bonus_data`);
UPDATE `dc_tmp_rank_map` AS `m` JOIN `spell_ranks` AS `r` ON `r`.`spell_id` = `m`.`top_id` SET `m`.`bonus_src` = `r`.`first_spell_id` WHERE `m`.`bonus_src` = 0 AND `r`.`first_spell_id` IN (SELECT `entry` FROM `spell_bonus_data`);
DELETE FROM `spell_bonus_data` WHERE `entry` BETWEEN 921000 AND 932999;

-- Rows registered under the level-80 rank's own id
DELETE FROM `spell_script_names` WHERE `spell_id` BETWEEN 921000 AND 932999;
DELETE FROM `spell_custom_attr` WHERE `spell_id` BETWEEN 921000 AND 932999;
DELETE FROM `spell_threat` WHERE `entry` BETWEEN 921000 AND 932999;
DELETE FROM `spell_linked_spell` WHERE `spell_trigger` BETWEEN 921000 AND 932999 OR `spell_trigger` BETWEEN -932999 AND -921000;

-- Weapon imbue enchantments: the proc rate of the level-80 enchantment, if it has one
DELETE FROM `spell_enchant_proc_data` WHERE `entry` IN (928131, 928132, 928133, 928134, 928361, 928362, 928363, 928364, 928381, 928382, 928383, 928384);

-- Totem creatures: one copy of the level-80 totem per band, numbered like the band's summon spell
-- and casting the band's copies of its spells. The creatures' ids share the spell id range.
DROP TEMPORARY TABLE IF EXISTS `dc_tmp_totem_map`;
CREATE TEMPORARY TABLE `dc_tmp_totem_map` (`new_entry` INT UNSIGNED NOT NULL PRIMARY KEY, `old_entry` INT UNSIGNED NOT NULL, `step` TINYINT UNSIGNED NOT NULL, `name` VARCHAR(100) NOT NULL) ENGINE=InnoDB;
DELETE FROM `dc_tmp_totem_map`;
DROP TEMPORARY TABLE IF EXISTS `dc_tmp_totem_template`;
CREATE TEMPORARY TABLE `dc_tmp_totem_template` ENGINE=InnoDB SELECT `t`.`new_entry` AS `dc_new_entry`, `t`.`name` AS `dc_new_name`, `ct`.* FROM `dc_tmp_totem_map` AS `t` JOIN `creature_template` AS `ct` ON `ct`.`entry` = `t`.`old_entry`;
UPDATE `dc_tmp_totem_template` SET `entry` = `dc_new_entry`, `name` = `dc_new_name`;
ALTER TABLE `dc_tmp_totem_template` DROP COLUMN `dc_new_entry`, DROP COLUMN `dc_new_name`;
-- REPLACE, not DELETE + INSERT: the codestyle rules never delete creature_template rows, and these
-- ids belong to this file alone.
DROP TEMPORARY TABLE IF EXISTS `dc_tmp_totem_addon`;
CREATE TEMPORARY TABLE `dc_tmp_totem_addon` ENGINE=InnoDB SELECT `t`.`new_entry` AS `dc_new_entry`, `a`.* FROM `dc_tmp_totem_map` AS `t` JOIN `creature_template_addon` AS `a` ON `a`.`entry` = `t`.`old_entry`;
UPDATE `dc_tmp_totem_addon` SET `entry` = `dc_new_entry`;
ALTER TABLE `dc_tmp_totem_addon` DROP COLUMN `dc_new_entry`;
DELETE FROM `creature_template_addon` WHERE `entry` BETWEEN 921000 AND 932999;
DELETE FROM `creature_template_model` WHERE `CreatureID` BETWEEN 921000 AND 932999;
DELETE FROM `creature_template_spell` WHERE `CreatureID` BETWEEN 921000 AND 932999;
DROP TEMPORARY TABLE `dc_tmp_totem_addon`;
DROP TEMPORARY TABLE `dc_tmp_totem_template`;
DROP TEMPORARY TABLE `dc_tmp_totem_map`;

-- Trap objects: one copy of the level-80 trap per band, numbered like the band's trap spell and
-- firing the band's copy of the trap's spell (Data3).
DROP TEMPORARY TABLE IF EXISTS `dc_tmp_trap_map`;
CREATE TEMPORARY TABLE `dc_tmp_trap_map` (`new_entry` INT UNSIGNED NOT NULL PRIMARY KEY, `old_entry` INT UNSIGNED NOT NULL, `step` TINYINT UNSIGNED NOT NULL, `name` VARCHAR(100) NOT NULL) ENGINE=InnoDB;
DELETE FROM `dc_tmp_trap_map`;
DROP TEMPORARY TABLE IF EXISTS `dc_tmp_trap_template`;
CREATE TEMPORARY TABLE `dc_tmp_trap_template` ENGINE=InnoDB SELECT `t`.`new_entry` AS `dc_new_entry`, `t`.`name` AS `dc_new_name`, `t`.`step` AS `dc_step`, `g`.* FROM `dc_tmp_trap_map` AS `t` JOIN `gameobject_template` AS `g` ON `g`.`entry` = `t`.`old_entry`;
UPDATE `dc_tmp_trap_template` AS `g` JOIN `dc_tmp_rank_map2` AS `r` ON `r`.`top_id` = `g`.`Data3` AND `r`.`step` = `g`.`dc_step` SET `g`.`entry` = `g`.`dc_new_entry`, `g`.`name` = `g`.`dc_new_name`, `g`.`Data3` = `r`.`new_id`;
ALTER TABLE `dc_tmp_trap_template` DROP COLUMN `dc_new_entry`, DROP COLUMN `dc_new_name`, DROP COLUMN `dc_step`;
-- REPLACE, not DELETE + INSERT: the codestyle rules never delete gameobject_template rows.
DROP TEMPORARY TABLE IF EXISTS `dc_tmp_trap_addon`;
CREATE TEMPORARY TABLE `dc_tmp_trap_addon` ENGINE=InnoDB SELECT `t`.`new_entry` AS `dc_new_entry`, `a`.* FROM `dc_tmp_trap_map` AS `t` JOIN `gameobject_template_addon` AS `a` ON `a`.`entry` = `t`.`old_entry`;
UPDATE `dc_tmp_trap_addon` SET `entry` = `dc_new_entry`;
ALTER TABLE `dc_tmp_trap_addon` DROP COLUMN `dc_new_entry`;
DELETE FROM `gameobject_template_addon` WHERE `entry` IN (924181, 924182, 924183, 924184, 924201, 924202, 924203, 924204);
DROP TEMPORARY TABLE `dc_tmp_trap_addon`;
DROP TEMPORARY TABLE `dc_tmp_trap_template`;
DROP TEMPORARY TABLE `dc_tmp_trap_map`;

DROP TEMPORARY TABLE `dc_tmp_rank_map2`;
DROP TEMPORARY TABLE `dc_tmp_rank_map`;
