INSERT INTO `creature_template_model` (`CreatureID`, `Idx`, `CreatureDisplayID`, `DisplayScale`, `Probability`, `VerifiedBuild`) SELECT `t`.`new_entry`, `m`.`Idx`, `m`.`CreatureDisplayID`, `m`.`DisplayScale`, `m`.`Probability`, 0 FROM `dc_tmp_totem_map` AS `t` JOIN `creature_template_model` AS `m` ON `m`.`CreatureID` = `t`.`old_entry`;
INSERT INTO `creature_template_spell` (`CreatureID`, `Index`, `Spell`, `VerifiedBuild`) SELECT `t`.`new_entry`, `s`.`Index`, CASE WHEN `r`.`new_id` IS NULL THEN `s`.`Spell` ELSE `r`.`new_id` END, 0 FROM `dc_tmp_totem_map` AS `t` JOIN `creature_template_spell` AS `s` ON `s`.`CreatureID` = `t`.`old_entry` LEFT JOIN `dc_tmp_rank_map2` AS `r` ON `r`.`top_id` = `s`.`Spell` AND `r`.`step` = `t`.`step`;
